import http from "node:http";
const root = process.env.PROBE_ROOT!;
const { LocalLlmClient } = await import(`${root}/cli/src/client.ts`);
const tool = { type: "function", function: { name: "read_file", description: "d", parameters: { type: "object", properties: { path: { type: "string" }, start_line: { type: "number" } }, required: ["path"] } } };
type Routes = Record<string, (body: string) => [number, any]>;
async function run(name: string, models: any, routes: Routes, env: Record<string, string> = {}, opts: { second?: boolean; secondModels?: [number, any] } = {}) {
  let chatHeaders: any = {}, chatBody: any = {}; const seen: string[] = [];
  let modelsMode = 0;
  const srv = http.createServer((req, res) => {
    let b = ""; req.on("data", (c) => (b += c)); req.on("end", () => {
      const key = `${req.method} ${req.url}`; seen.push(key);
      res.setHeader("content-type", "application/json");
      if (key === "GET /v1/models") {
        if (modelsMode === 1 && opts.secondModels) { res.statusCode = opts.secondModels[0]; return void res.end(JSON.stringify(opts.secondModels[1])); }
        return void res.end(JSON.stringify({ data: [models] }));
      }
      if (key === "POST /v1/chat/completions") { chatHeaders = req.headers; try { chatBody = JSON.parse(b); } catch {} return void res.end(JSON.stringify({ choices: [{ message: { role: "assistant", content: "ok" }, finish_reason: "stop" }], usage: {} })); }
      const r = routes[key]; if (r) { const [s, j] = r(b); res.statusCode = s; return void res.end(JSON.stringify(j)); }
      res.statusCode = 404; res.end("{}");
    });
  });
  await new Promise<void>((r) => srv.listen(0, "127.0.0.1", r));
  const port = (srv.address() as any).port;
  const old: Record<string, string | undefined> = {};
  for (const [k, v] of Object.entries(env)) { old[k] = process.env[k]; process.env[k] = v; }
  try {
    const ep = `http://127.0.0.1:${port}/v1`;
    const c = new LocalLlmClient({ model: "m", endpoint: ep, apiKey: "k", taskClass: "subagent", workspace: "/tmp", maxSteps: 1 } as any);
    const d = await c.discoverAdvertisement();
    if (opts.second) { modelsMode = 1; const d2 = await c.discoverAdvertisement(); seen.push(`(2nd discovery -> ${d2.state})`); }
    await c.chatCompletion([{ role: "user", content: "hi" }], [tool] as any);
    const st = chatBody.tools?.[0]?.function;
    console.log(JSON.stringify({ name, state: d.state, via: d.advertised?.via, ctx: d.advertised?.contextLength, kind: (c as any).getDetectedServerKind?.(), taskClass: chatHeaders["x-task-class"] ?? null, strict: st?.strict ?? null, gramm: chatBody.grammar !== undefined || chatBody.response_format !== undefined, seen: seen.filter(s => s !== "POST /v1/chat/completions") }));
  } finally { for (const [k, v] of Object.entries(old)) { if (v === undefined) delete process.env[k]; else process.env[k] = v; } srv.close(); }
}
const ok = (j: any) => () => [200, j] as [number, any];
const nf = () => [404, {}] as [number, any];
await run("1 llamacpp marker + /props ok", { id: "m", owned_by: "llamacpp", meta: { n_ctx_train: 32768 } }, { "GET /props": ok({ default_generation_settings: { n_ctx: 16384 } }) });
await run("2 llamacpp marker, /props 404", { id: "m", owned_by: "llamacpp", meta: { n_ctx_train: 32768 } }, {});
