await run("11 llamacpp ok then 2nd discovery /models 500", { id: "m", owned_by: "llamacpp", meta: { n_ctx_train: 32768 } }, { "GET /props": ok({ default_generation_settings: { n_ctx: 16384 } }) }, {}, { second: true, secondModels: [500, {}] });
